BEGIN;
CREATE TABLE IF NOT EXISTS proof_users(id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS proof_tenants(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS proof_memberships(tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),user_id BIGINT NOT NULL REFERENCES proof_users(id),role TEXT NOT NULL CHECK(role IN('creator','editor','reviewer','render_operator','publisher','auditor','admin')),active BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS proof_evidence_sources(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),source_ref TEXT NOT NULL,source_type TEXT NOT NULL,subject_ref TEXT NOT NULL,source JSONB NOT NULL,evidence_digest CHAR(64) NOT NULL,ingested_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,source_ref),UNIQUE(tenant_id,evidence_digest));
CREATE TABLE IF NOT EXISTS proof_projects(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),title TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN('draft','editing','render_queued','render_failed','review_pending','rejected','approved','publish_queued','publish_failed','published','exported')),revision INTEGER NOT NULL DEFAULT 1,created_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS proof_versions(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),project_id BIGINT NOT NULL REFERENCES proof_projects(id),parent_version_id BIGINT REFERENCES proof_versions(id),version_ref TEXT NOT NULL,locale TEXT NOT NULL,content JSONB NOT NULL,version_digest CHAR(64) NOT NULL,created_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,project_id,version_ref),UNIQUE(tenant_id,version_digest));
CREATE TABLE IF NOT EXISTS proof_assets(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),version_id BIGINT NOT NULL REFERENCES proof_versions(id),evidence_source_id BIGINT NOT NULL REFERENCES proof_evidence_sources(id),asset_ref TEXT NOT NULL,asset JSONB NOT NULL,asset_digest CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,version_id,asset_ref));
CREATE TABLE IF NOT EXISTS proof_segmentation_runs(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),rule_version TEXT NOT NULL,input_digest CHAR(64) NOT NULL,result JSONB NOT NULL,result_digest CHAR(64) NOT NULL,created_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,input_digest,result_digest));
CREATE TABLE IF NOT EXISTS proof_selection_runs(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),segmentation_run_id BIGINT NOT NULL REFERENCES proof_segmentation_runs(id),rule_version TEXT NOT NULL,result JSONB NOT NULL,result_digest CHAR(64) NOT NULL,created_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,segmentation_run_id,result_digest));
CREATE TABLE IF NOT EXISTS proof_render_jobs(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),version_id BIGINT NOT NULL REFERENCES proof_versions(id),idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','retry','succeeded','dead_letter')),request JSONB NOT NULL,request_digest CHAR(64) NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),artifact_uri TEXT,artifact_digest CHAR(64),provider_ref TEXT,last_error_code TEXT,created_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS proof_quality_evaluations(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),version_id BIGINT NOT NULL REFERENCES proof_versions(id),render_job_id BIGINT NOT NULL REFERENCES proof_render_jobs(id),evaluation JSONB NOT NULL,evaluation_digest CHAR(64) NOT NULL,passed BOOLEAN NOT NULL,evaluated_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,render_job_id,evaluation_digest));
CREATE TABLE IF NOT EXISTS proof_moderation_decisions(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),version_id BIGINT NOT NULL REFERENCES proof_versions(id),decision TEXT NOT NULL CHECK(decision IN('approved','rejected','escalated')),policy_version TEXT NOT NULL,evidence_digest CHAR(64) NOT NULL,decided_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,version_id,evidence_digest));
CREATE TABLE IF NOT EXISTS proof_approvals(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),project_id BIGINT NOT NULL REFERENCES proof_projects(id),version_id BIGINT NOT NULL REFERENCES proof_versions(id),quality_evaluation_id BIGINT NOT NULL REFERENCES proof_quality_evaluations(id),moderation_decision_id BIGINT NOT NULL REFERENCES proof_moderation_decisions(id),approval JSONB NOT NULL,approval_digest CHAR(64) NOT NULL,approved_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,project_id,approval_digest));
CREATE TABLE IF NOT EXISTS proof_publication_jobs(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),approval_id BIGINT NOT NULL REFERENCES proof_approvals(id),channel TEXT NOT NULL,idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','retry','succeeded','dead_letter')),payload JSONB NOT NULL,payload_digest CHAR(64) NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),external_ref TEXT,evidence_digest CHAR(64),last_error_code TEXT,created_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS proof_provider_usage(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),provider TEXT NOT NULL,operation TEXT NOT NULL,usage JSONB NOT NULL,usage_digest CHAR(64) NOT NULL,evidence_digest CHAR(64) NOT NULL,recorded_by BIGINT NOT NULL REFERENCES proof_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,usage_digest));
CREATE TABLE IF NOT EXISTS proof_provider_failures(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),provider TEXT NOT NULL,operation TEXT NOT NULL,error_code TEXT NOT NULL,retryable BOOLEAN NOT NULL,sanitized_detail TEXT NOT NULL DEFAULT 'provider detail redacted',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS proof_events(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES proof_tenants(id),project_id BIGINT REFERENCES proof_projects(id),actor_id BIGINT REFERENCES proof_users(id),event_type TEXT NOT NULL,payload JSONB NOT NULL,evidence_digest CHAR(64),occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS proof_render_ready_idx ON proof_render_jobs(status,next_attempt_at);CREATE INDEX IF NOT EXISTS proof_publish_ready_idx ON proof_publication_jobs(status,next_attempt_at);CREATE INDEX IF NOT EXISTS proof_project_state_idx ON proof_projects(tenant_id,state,updated_at);
CREATE OR REPLACE FUNCTION prevent_proof_evidence_mutation() RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'social proof evidence is append-only';END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION guard_proof_render_request() RETURNS trigger AS $$BEGIN IF OLD.tenant_id<>NEW.tenant_id OR OLD.version_id<>NEW.version_id OR OLD.idempotency_key<>NEW.idempotency_key OR OLD.request IS DISTINCT FROM NEW.request OR OLD.request_digest<>NEW.request_digest OR OLD.created_by<>NEW.created_by OR OLD.created_at<>NEW.created_at THEN RAISE EXCEPTION 'render request evidence is immutable';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION guard_proof_publication_request() RETURNS trigger AS $$BEGIN IF OLD.tenant_id<>NEW.tenant_id OR OLD.approval_id<>NEW.approval_id OR OLD.channel<>NEW.channel OR OLD.idempotency_key<>NEW.idempotency_key OR OLD.payload IS DISTINCT FROM NEW.payload OR OLD.payload_digest<>NEW.payload_digest OR OLD.created_by<>NEW.created_by OR OLD.created_at<>NEW.created_at THEN RAISE EXCEPTION 'publication request evidence is immutable';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
DO $$DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['proof_evidence_sources','proof_versions','proof_assets','proof_segmentation_runs','proof_selection_runs','proof_quality_evaluations','proof_moderation_decisions','proof_approvals','proof_provider_usage','proof_events'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_append_only ON %I',t,t);EXECUTE format('CREATE TRIGGER %I_append_only BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_proof_evidence_mutation()',t,t);END LOOP;END$$;
DROP TRIGGER IF EXISTS proof_render_request_guard ON proof_render_jobs;CREATE TRIGGER proof_render_request_guard BEFORE UPDATE ON proof_render_jobs FOR EACH ROW EXECUTE FUNCTION guard_proof_render_request();
DROP TRIGGER IF EXISTS proof_publication_request_guard ON proof_publication_jobs;CREATE TRIGGER proof_publication_request_guard BEFORE UPDATE ON proof_publication_jobs FOR EACH ROW EXECUTE FUNCTION guard_proof_publication_request();
COMMIT;
